-- ============================================================================
-- idle-store-commodity MySQL 初始化脚本
--
-- 商品图片不保存访问 URL，只保存 OSS 文件 ID；分类仍沿用 icon_url，待分类更新链路重构时再迁移。
-- file_id 指向 OSS 服务的 t_file_object.file_id，不建立跨服务数据库外键。
-- 历史商品图片登记为 ALIYUN_OSS 文件记录，需保留对应的存储配置以继续读取。
-- ============================================================================

-- ----------------------------
-- Table structure for t_commodity
-- ----------------------------
DROP TABLE IF EXISTS `t_commodity`;
CREATE TABLE `t_commodity` (
  `commodity_id` bigint NOT NULL COMMENT '商品ID',
  `category_id` bigint unsigned NOT NULL COMMENT '商品分类ID',
  `seller_id` bigint unsigned NOT NULL COMMENT '发布用户ID',
  `community_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '所属社区ID',
  `image_file_ids` json NOT NULL COMMENT '商品图片文件ID数组，第一张作为封面',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '商品单价',
  `total_quantity` int unsigned NOT NULL DEFAULT '1' COMMENT '商品总数量',
  `sold_quantity` int unsigned NOT NULL DEFAULT '0' COMMENT '已售数量',
  `status` tinyint unsigned NOT NULL COMMENT '商品状态，具体值由CommodityStatusEnum定义',
  `logistics_mode` int unsigned NOT NULL DEFAULT '0' COMMENT '交付方式位标记，具体值由LogisticsModeEnum定义',
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品描述',
  `drainage_plan` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否参加引流计划：0否，1是',
  `commodity_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删除，1已删除',
  PRIMARY KEY (`commodity_id`),
  KEY `idx_commodity_community_list` (`community_id`,`status`,`is_deleted`,`publish_time`),
  KEY `idx_commodity_seller_list` (`seller_id`,`is_deleted`,`status`,`publish_time`),
  KEY `idx_commodity_category_list` (`category_id`,`status`,`is_deleted`,`publish_time`),
  CONSTRAINT `chk_commodity_deleted` CHECK ((`is_deleted` in (0,1))),
  CONSTRAINT `chk_commodity_drainage` CHECK ((`drainage_plan` in (0,1))),
  CONSTRAINT `chk_commodity_price` CHECK ((`price` >= 0)),
  CONSTRAINT `chk_commodity_quantity` CHECK (((`total_quantity` > 0) and (`sold_quantity` <= `total_quantity`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='闲置商品表';

-- ----------------------------
-- Records of t_commodity
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for t_commodity_category
-- ----------------------------
DROP TABLE IF EXISTS `t_commodity_category`;
CREATE TABLE `t_commodity_category` (
  `category_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `parent_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '父分类ID，0表示一级分类',
  `category_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称',
  `icon_url` bigint unsigned DEFAULT NULL COMMENT '分类图标文件ID，关联 OSS 服务文件元数据',
  `sort_order` int unsigned NOT NULL DEFAULT '0' COMMENT '同级分类排序，越小越靠前',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态：0禁用，1启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删除，1已删除',
  PRIMARY KEY (`category_id`),
  UNIQUE KEY `uk_category_parent_name` (`parent_id`,`category_name`),
  KEY `idx_category_parent_list` (`parent_id`,`status`,`is_deleted`,`sort_order`),
  KEY `idx_category_icon_url` (`icon_url`),
  CONSTRAINT `chk_category_deleted` CHECK ((`is_deleted` in (0,1))),
  CONSTRAINT `chk_category_status` CHECK ((`status` in (0,1)))
) ENGINE=InnoDB AUTO_INCREMENT=108 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='商品分类表';

-- ----------------------------
-- Records of t_commodity_category
-- ----------------------------
BEGIN;
COMMIT;
